<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { api } from './api'

const keys=ref([]),logs=ref([]),workspaces=ref([]),scopes=ref([]),loading=ref(false),creating=ref(false),error=ref(''),newToken=ref(''),tab=ref('keys')
const form=reactive({name:'Production',scopes:[]})
const apiBase=(import.meta.env.VITE_API_BASE_URL||'http://localhost:8000/api/v1').replace(/\/$/,'')
const currentWorkspace=computed(()=>workspaces.value.length===1?workspaces.value[0]:null)
const curlExample=computed(()=>`curl -H "Authorization: Bearer ${newToken.value||'wac_live_YOUR_API_KEY'}" \\\n  "${apiBase}/subscribers?channel=whatsapp"`)
const triggerExample=computed(()=>`curl -X POST \\\n  -H "Authorization: Bearer ${newToken.value||'wac_live_YOUR_API_KEY'}" \\\n  -H "Content-Type: application/json" \\\n  "${apiBase}/bot-flows/12/trigger" \\\n  -d '{"subscriber":"27829640758","fields":{"order_number":"ORD-12345"}}'`)

async function load(){loading.value=true;error.value='';try{const [k,l,w,s]=await Promise.all([api.developerApiKeys(),api.developerApiLogs(),api.developerApiWorkspaces(),api.developerApiScopes()]);keys.value=k;logs.value=l;workspaces.value=w;scopes.value=s;if(!form.scopes.length)form.scopes=[...s]}catch(e){error.value=e.message}finally{loading.value=false}}
async function createKey(){if(creating.value)return;creating.value=true;error.value='';newToken.value='';try{const payload={name:form.name,scopes:form.scopes};if(currentWorkspace.value)payload.workspace_id=currentWorkspace.value.id;const row=await api.createDeveloperApiKey(payload);newToken.value=row.token;keys.value=[row,...keys.value]}catch(e){error.value=e.message}finally{creating.value=false}}
async function revokeKey(row){if(!confirm(`Revoke API key “${row.name}”? Applications using it will stop working immediately.`))return;try{await api.revokeDeveloperApiKey(row.id);row.active=false;row.revoked_at=new Date().toISOString()}catch(e){error.value=e.message}}
function toggleAll(){form.scopes=form.scopes.length===scopes.value.length?[]:[...scopes.value]}
function formatDate(v){return v?new Intl.DateTimeFormat(undefined,{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'Never'}
onMounted(load)
</script>

<template><section class="dev-page"><header><div><p class="eyebrow">Integrations</p><h1>Developer API</h1><p>Create secure API keys and integrate WA Connect subscribers, custom fields and bot flows with external systems.</p></div><button class="refresh" @click="load">{{loading?'Refreshing…':'↻ Refresh'}}</button></header>
<div class="tabs"><button :class="{active:tab==='keys'}" @click="tab='keys'">API Keys</button><button :class="{active:tab==='docs'}" @click="tab='docs'">Quick Start</button><button :class="{active:tab==='logs'}" @click="tab='logs'">Request Logs</button></div>
<p v-if="error" class="error">{{error}}</p>

<template v-if="tab==='keys'"><div v-if="newToken" class="token-card"><div><p class="eyebrow">Created successfully</p><h3>Copy this key now</h3><p>For security, the full API key is only shown once.</p></div><code>{{newToken}}</code><button @click="newToken=''">I've saved it</button></div>
<div class="keys-layout"><form class="card create" @submit.prevent="createKey"><h2>Create API key</h2><label>Name<input v-model="form.name" required maxlength="120" placeholder="Production"/></label><div class="workspace-auto"><span>Workspace</span><strong>{{currentWorkspace?currentWorkspace.name:'Current workspace'}}</strong><small>API keys are automatically restricted to your active WA Connect workspace.</small></div><div class="scope-head"><strong>Permissions</strong><button type="button" @click="toggleAll">{{form.scopes.length===scopes.length?'Clear all':'Select all'}}</button></div><label v-for="scope in scopes" :key="scope" class="scope"><input v-model="form.scopes" type="checkbox" :value="scope"/><span><b>{{scope}}</b><small>{{scope.endsWith(':read')?'Read data':scope==='flows:trigger'?'Start bot flows':'Modify data'}}</small></span></label><button class="primary" :disabled="creating||!form.scopes.length">{{creating?'Generating…':'Generate API key'}}</button></form>
<div class="card list"><div class="card-head"><div><h2>API keys</h2><p>Only the key prefix is stored for display. The secret itself is hashed.</p></div><span>{{keys.length}}</span></div><article v-for="row in keys" :key="row.id" class="key-row"><div class="key-main"><strong>{{row.name}}</strong><code>{{row.prefix}}••••••••••••••</code><small>Created {{formatDate(row.created_at)}} · Last used {{formatDate(row.last_used_at)}}</small><div class="chips"><i v-for="scope in row.scopes" :key="scope">{{scope}}</i></div></div><div class="key-state"><span :class="{off:!row.active}">{{row.active?'ACTIVE':'REVOKED'}}</span><button v-if="row.active" @click="revokeKey(row)">Revoke</button></div></article><div v-if="!keys.length" class="empty">No Developer API keys yet.</div></div></div></template>

<template v-else-if="tab==='docs'"><div class="docs-grid"><article class="card"><p class="eyebrow">Authentication</p><h2>Bearer API keys</h2><p>Send your key in the <code>Authorization</code> header. Keys are workspace-scoped and permission-scoped.</p><pre>{{curlExample}}</pre></article><article class="card"><p class="eyebrow">Flow automation</p><h2>Trigger a bot flow</h2><p>Trigger an active WhatsApp or Telegram flow and optionally populate custom fields before it starts.</p><pre>{{triggerExample}}</pre></article></div><div class="card endpoints"><h2>Developer API v1</h2><div class="endpoint" v-for="e in [
['GET','/subscribers','List WhatsApp and Telegram subscribers'],['POST','/subscribers','Create a WhatsApp subscriber'],['GET','/subscribers/{id}','Get one subscriber'],['PATCH','/subscribers/{id}','Update subscriber profile'],['DELETE','/subscribers/{id}','Archive/delete a subscriber'],['GET','/custom-fields','List available custom fields'],['GET','/subscribers/{id}/fields','Read subscriber fields'],['PATCH','/subscribers/{id}/fields','Set fields by stable key'],['GET','/tags','List tags'],['POST','/subscribers/{id}/tags','Assign or create a tag'],['DELETE','/subscribers/{id}/tags/{tag_id}','Remove a tag'],['PATCH','/subscribers/{id}/conversation','Assign agent or change status'],['GET','/bot-flows','List channel flows'],['POST','/bot-flows/{flow_id}/trigger','Trigger an active bot flow']
]" :key="e[0]+e[1]"><b :class="e[0].toLowerCase()">{{e[0]}}</b><code>{{e[1]}}</code><span>{{e[2]}}</span></div><p class="note">Subscriber IDs returned by the API use stable references such as <code>whatsapp:144</code> or <code>telegram:27</code>. Trigger Flow accepts the channel-native subscriber ID (for WhatsApp, the phone number; for Telegram, the Telegram user ID).</p></div></template>

<template v-else><div class="card logs"><div class="card-head"><div><h2>Recent API requests</h2><p>Latest requests made with Developer API keys.</p></div><span>{{logs.length}}</span></div><div class="log-head"><b>Time</b><b>Method</b><b>Path</b><b>Status</b><b>Duration</b></div><div v-for="row in logs" :key="row.id" class="log-row"><span>{{formatDate(row.created_at)}}</span><b>{{row.method}}</b><code>{{row.path}}</code><strong :class="{bad:row.status_code>=400}">{{row.status_code}}</strong><span>{{row.duration_ms}} ms</span></div><div v-if="!logs.length" class="empty">No Developer API requests logged yet.</div></div></template>
</section></template>

<style scoped>
.dev-page{margin-left:220px;padding:34px 38px;min-height:100vh;background:#f4f7f6;color:#173126}.dev-page>header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:22px}.dev-page h1{font-size:30px;margin:3px 0 6px}.dev-page header p:last-child,.card p{color:#74867e;margin:0}.eyebrow{text-transform:uppercase!important;color:#119052!important;font-size:11px!important;font-weight:800;letter-spacing:.08em;margin:0!important}.refresh{border:1px solid #d4dfda;background:#fff;border-radius:9px;padding:10px 14px}.tabs{display:flex;gap:6px;border-bottom:1px solid #dce5e1;margin-bottom:20px}.tabs button{border:0;background:transparent;padding:11px 14px;color:#65776f;cursor:pointer}.tabs button.active{color:#087943;border-bottom:2px solid #18a45e;font-weight:800}.card{background:#fff;border:1px solid #dfe7e3;border-radius:14px;padding:22px}.keys-layout{display:grid;grid-template-columns:340px minmax(0,1fr);gap:18px}.create{display:flex;flex-direction:column;gap:13px}.create h2,.card h2{margin:0 0 6px;font-size:19px}.create label:not(.scope){display:grid;gap:6px;font-size:12px;font-weight:700}.create input[type=text],.create input:not([type]){border:1px solid #d4ded9;border-radius:9px;padding:10px 11px;min-height:40px;background:#fff}.workspace-auto{display:grid;gap:4px;border:1px solid #dce6e1;background:#f6faf8;border-radius:9px;padding:10px 11px}.workspace-auto span{font-size:11px;color:#6f8178}.workspace-auto strong{font-size:13px}.workspace-auto small{color:#84938c;line-height:1.35}.scope-head{display:flex;justify-content:space-between;align-items:center;margin-top:4px}.scope-head button{border:0;background:transparent;color:#168452;font-weight:700;cursor:pointer}.scope{display:flex;align-items:flex-start;gap:9px;font-size:12px}.scope input{margin-top:3px}.scope b,.scope small{display:block}.scope small{font-weight:400;color:#839089;margin-top:2px}.primary{border:0;background:#12a65a;color:white;border-radius:9px;padding:11px 14px;font-weight:800}.primary:disabled{opacity:.55}.card-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;border-bottom:1px solid #edf1ef;padding-bottom:14px}.card-head p{font-size:12px;margin-top:5px}.card-head>span{background:#e7f7ee;color:#117947;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800}.key-row{display:flex;justify-content:space-between;gap:16px;padding:17px 0;border-bottom:1px solid #edf1ef}.key-main strong,.key-main code,.key-main small{display:block}.key-main code{margin:6px 0;background:#f3f6f5;padding:5px 7px;border-radius:6px;width:max-content}.key-main small{color:#829088}.chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:10px}.chips i{font-style:normal;font-size:9px;background:#eef5f1;color:#537066;border-radius:999px;padding:4px 7px}.key-state{text-align:right}.key-state span{display:block;color:#14834f;background:#e7f7ee;border-radius:999px;padding:5px 8px;font-size:9px;font-weight:900}.key-state span.off{color:#8b5656;background:#f8eded}.key-state button{margin-top:9px;border:1px solid #e1caca;background:#fff;color:#9b3333;border-radius:7px;padding:6px 9px}.token-card{background:#eaf8f0;border:1px solid #a8dfc0;border-radius:14px;padding:18px 20px;margin-bottom:18px}.token-card h3{margin:3px 0}.token-card code{display:block;background:#102c21;color:#d9f7e7;padding:13px;border-radius:8px;margin:13px 0;word-break:break-all}.token-card button{border:0;background:transparent;color:#107d49;font-weight:800;padding:0}.docs-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:18px}.docs-grid pre{white-space:pre-wrap;word-break:break-word;background:#102c21;color:#dcf4e8;padding:14px;border-radius:9px;margin:16px 0 0;font-size:11px}.endpoints{padding-bottom:16px}.endpoint{display:grid;grid-template-columns:62px 300px minmax(0,1fr);gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid #edf1ef}.endpoint>b{font-size:10px;border-radius:5px;padding:4px 6px;text-align:center;background:#e9f6ef;color:#168452}.endpoint>b.post{background:#e9f1fb;color:#316aa0}.endpoint>b.patch{background:#fff4df;color:#936a18}.endpoint>b.delete{background:#faecec;color:#a33}.endpoint span{color:#71837a;font-size:12px}.note{font-size:12px;margin-top:15px!important}.log-head,.log-row{display:grid;grid-template-columns:190px 70px minmax(260px,1fr) 70px 80px;gap:10px;align-items:center}.log-head{padding:12px 0;color:#6e7e76;font-size:11px}.log-row{padding:11px 0;border-top:1px solid #edf1ef;font-size:11px}.log-row code{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.log-row strong{color:#168452}.log-row strong.bad{color:#a33}.empty{padding:25px 0;text-align:center;color:#86938d}.error{background:#fff0f0;color:#922f2f;padding:10px 13px;border-radius:8px}@media(max-width:1000px){.keys-layout,.docs-grid{grid-template-columns:1fr}.endpoint{grid-template-columns:62px 1fr}.endpoint span{grid-column:2}.log-head,.log-row{grid-template-columns:140px 60px 1fr 55px}.log-head>*:last-child,.log-row>*:last-child{display:none}}
</style>
